actions.script:
import groovy.json.JsonSlurper
import groovy.json.JsonOutput

ec.logger.info("🚀 [TOOL EXECUTION] add#FormField called with: targetNodeId=${targetNodeId}, name=${name}, label=${label}, encrypt=${encrypt}")
boolean secureField = "true".equalsIgnoreCase(encrypt)

// 🎯 ROBUST TARGET URI RESOLUTION FROM targetNodeId OR CONTEXT
String targetUri = ""
if (targetNodeId && targetNodeId.contains("#") && targetNodeId.startsWith("component://")) {
    targetUri = targetNodeId.split("#")[0]
}

if (!targetUri || targetUri.trim() == "") {
    String rawUri = context.activeArtifactLocation ?: ec.context.activeArtifactLocation ?: context.focusCoordinate ?: ""
    targetUri = rawUri.contains("#") ? rawUri.split("#")[0] : rawUri
}

if (!targetUri || targetUri.trim() == "") {
    targetUri = (ec.context.get("activeArtifactLocation") ?: "").toString()
}

String rawName = context.name ?: ""
String cleanName = (rawName.trim() != "") 
    ? rawName.trim() 
    : label.replaceAll("[^a-zA-Z0-9_]", "")

ec.logger.info("ℹ️ [add#FormField] Resolved field cleanName: ${cleanName}, targetUri: '${targetUri}'")

String currentMetaJsonStr = context.activeLayoutBuffer
String bufferId = context.activeLayoutBufferId

String activeSessionId = context.sessionId ?: ec.context.sessionId
String activeUserId = ec.user.getUserId() ?: "system_ide_user"

// 🎯 1. CHECK ADK SESSION STATE FOR VALID JSON
if (activeSessionId) {
    def runner = org.moqui.adk.AdkManager.runnerForSession(activeSessionId)
    def sessionOpt = runner.sessionService().getSession("moqui-adk", activeUserId, activeSessionId, java.util.Optional.empty()).blockingGet()

    if (sessionOpt && sessionOpt.isPresent()) {
        Map adkState = sessionOpt.get().state()
        String stateBuffer = adkState.get("activeLayoutBuffer")
        if (stateBuffer && stateBuffer.startsWith("{")) {
            currentMetaJsonStr = stateBuffer
        }
    }
}

// 🎯 2. ALWAYS PREFER DATABASE BUFFER ROW IF currentMetaJsonStr IS INVALID OR NOT JSON
if (!currentMetaJsonStr || !currentMetaJsonStr.trim().startsWith("{")) {
    if (targetUri && targetUri.trim() != "") {
        def bufferRow = ec.entity.find("org.moqui.ai.WorkspaceBuffer")
            .condition("artifactUri", targetUri)
            .condition("userId", activeUserId)
            .one()
        if (bufferRow?.metaJsonBuffer) {
            currentMetaJsonStr = bufferRow.metaJsonBuffer
            bufferId = bufferRow.workspaceBufferId
            ec.logger.info("🎯 [add#FormField] Hydrated buffer from WorkspaceBuffer DB row: ${bufferId}")
        }
    }
}

ec.logger.info("ℹ️ [add#FormField] Working Meta-JSON Content: ${currentMetaJsonStr}")

// 🎯 3. SAFE PARSING WITH CORRUPTION RECOVERY
Map layoutTree = [:]
boolean parseFailed = false

if (currentMetaJsonStr && currentMetaJsonStr.trim().startsWith("{") && !currentMetaJsonStr.contains("[...]")) {
    try {
        layoutTree = new JsonSlurper().parseText(currentMetaJsonStr) as Map
    } catch (Exception parseEx) {
        ec.logger.warn("⚠️ [add#FormField] Invalid JSON buffer in DB/State (${parseEx.message}). Triggering auto-recovery...")
        parseFailed = true
    }
} else {
    parseFailed = true
}

if (parseFailed || layoutTree.isEmpty()) {
    ec.logger.info("🛠️ [add#FormField] Building fresh root layout tree structure for URI: '${targetUri}'")
    String screenName = targetUri ? targetUri.split("/")[-1].replace(".xml", "") : "ActiveScreen"
    layoutTree = [
        screen: screenName,
        location: targetUri ?: "",
        mariaId: screenName + "#root",
        widgets: [
            [
                type: "form-single",
                id: "patient_intake",
                mariaId: (targetUri ?: "") + "#patient_intake",
                children: []
            ]
        ]
    ]
}

// Build target node
Map dynamicFieldNode = [
    id: java.util.UUID.randomUUID().toString(),
    type: "FormField",
    name: cleanName,
    title: label,
    mariaId: targetUri + "#" + cleanName,
    children: []
]

// Execute tree mutation
Map mutationResult = ec.service.sync().name("org.moqui.ai.mcp.LayoutServices.mutate#JsonTree")
    .parameters([layoutTree: layoutTree, targetNodeId: targetNodeId, action: "APPEND", payloadNode: dynamicFieldNode])
    .call()

if (mutationResult.mutated) {
    String updatedMetaJson = JsonOutput.toJson(layoutTree)

    // 🎯 DIRECT ENTITY UPDATE (Bypasses service validation wrapper)
    def bufferEntity = null
    if (bufferId) {
        bufferEntity = ec.entity.find("org.moqui.ai.WorkspaceBuffer")
            .condition("workspaceBufferId", bufferId)
            .one()
    }
    if (!bufferEntity && targetUri) {
        bufferEntity = ec.entity.find("org.moqui.ai.WorkspaceBuffer")
            .condition("artifactUri", targetUri)
            .condition("userId", activeUserId)
            .one()
    }

    if (bufferEntity) {
        bufferEntity.metaJsonBuffer = updatedMetaJson
        bufferEntity.update()
        ec.logger.info("💾 [add#FormField] DIRECT ENTITY UPDATE SUCCESS on ID [${bufferEntity.workspaceBufferId}] for URI: ${targetUri}")
    } else {
        // Create new row if none exists
        def newBuffer = ec.entity.makeValue("org.moqui.ai.WorkspaceBuffer")
        newBuffer.artifactUri = targetUri
        newBuffer.userId = activeUserId
        newBuffer.metaJsonBuffer = updatedMetaJson
        newBuffer.setSequencedIdPrimary()
        newBuffer.create()
        ec.logger.info("💾 [add#FormField] CREATED new WorkspaceBuffer row [${newBuffer.workspaceBufferId}]")
    }

    // Update in-memory ADK Session State
    if (activeSessionId) {
        def runner = org.moqui.adk.AdkManager.runnerForSession(activeSessionId)
        def sessionOpt = runner.sessionService().getSession("moqui-adk", activeUserId, activeSessionId, java.util.Optional.empty()).blockingGet()
        if (sessionOpt && sessionOpt.isPresent()) {
            sessionOpt.get().state().put("activeLayoutBuffer", updatedMetaJson)
        }
    }

    context.updatedMetaJson = updatedMetaJson
    context.status = "SUCCESS"
} else {
    ec.logger.warn("❌ [TOOL MUTATION FAILED] Target node container [${targetNodeId}] was NOT found in active tree buffer.")
    context.status = "NODE_NOT_FOUND"
}

ec.logger.info("[TOOL MUTATION] targetNodeId: ${targetNodeId}")
ec.logger.info("[TOOL MUTATION] action: ${action}")
ec.logger.info("[TOOL MUTATION] payloadNode: ${payloadNode}")

def processNode
processNode = { Map node ->
    String cleanTargetId = targetNodeId.contains("#") ? targetNodeId.split("#")[1] : targetNodeId

    boolean isTarget = (node.id == targetNodeId) || 
        (node.mariaId == targetNodeId) || 
        (node.id == cleanTargetId) ||
        (node.name == cleanTargetId) ||
        (node.mariaId?.toString()?.endsWith("#" + cleanTargetId))

    if (isTarget) {
        switch (action) {
            case "APPEND":
                if (node.widgets != null) {
                    node.widgets.add(payloadNode)
                } else {
                    if (node.children == null) node.children = []
                    node.children.add(payloadNode)
                }
                return true
            case "REPLACE":
                node.clear()
                node.putAll(payloadNode)
                return true
        }
    }

    def childList = node.widgets ?: node.children
    if (childList && childList instanceof List) {
        if (action == "DELETE") {
            boolean removed = childList.removeIf { 
                it.id == targetNodeId || it.mariaId == targetNodeId || it.mariaId?.toString()?.endsWith("#" + targetNodeId)
            }
            if (removed) return true
        }
        for (child in childList) {
            if (child instanceof Map && processNode(child as Map)) return true
        }
    }
    return false
}
context.mutated = processNode(layoutTree)
